@dataclass(kw_only=True)
class ChatSFTPreprocessingConfig:
    """Declarative preprocessing for structured conversation examples.

    Args:
        loss_mode: Tokens that contribute to the loss. ``assistant`` trains all
            assistant turns, ``last_turn`` trains only the final assistant span,
            and ``full`` trains the complete rendered conversation.
    """

    loss_mode: Literal["assistant", "last_turn", "full"] = "assistant"

    def validate(self) -> None:
        """Validate chat preprocessing settings."""
        if self.loss_mode not in {"assistant", "last_turn", "full"}:
            raise ValueError("Chat SFT loss_mode must be assistant, last_turn, or full.")

assert config.checkpoint.pretrained_checkpoint is not None or config.checkpoint.load is not None, (
    "Finetuning requires a loading from a pretrained checkpoint or resuming from a checkpoint"
)
config._checkpoint_load_required = True
return pretrain(config, forward_step_func, callbacks=callbacks)

num_tokens = loss_mask.sum().clone().detach().to(torch.int)
reporting_loss = torch.cat([loss.clone().detach().view(1), num_tokens.view(1)])

return (loss, num_tokens, {"lm loss": reporting_loss})

assert self.vocab_size is not None, "vocab_size must be configured before calling provide()"
if self.should_pad_vocab:
    padded_vocab_size = calculate_padded_vocab_size(
        self.vocab_size, self.make_vocab_size_divisible_by, self.tensor_model_parallel_size
    )
else:
    padded_vocab_size = self.vocab_size

def hf_to_megatron(
    self,
    hf_weights: Dict[str, torch.Tensor],
    megatron_module: nn.Module,
) -> torch.Tensor:
    """Merge Q, K, V into interleaved format and distribute."""
    if self.tp_rank == 0:
        config = self._get_config(megatron_module)

        # Check if we're dealing with biases (1D tensors) or hf_weights (2D tensors)
        if hf_weights["q"].ndim == 1:
            # For biases, use the bias-specific merge function
            merged = merge_qkv_biases(config, hf_weights["q"], hf_weights["k"], hf_weights["v"])
        else:
            # For hf_weights, use the standard merge function
            merged = merge_qkv_weights(config, hf_weights["q"], hf_weights["k"], hf_weights["v"])
    else:
        merged = None

    # Delegate the actual sharding/broadcasting to the TP-aware mapping.
    return self._tp_mapping.hf_to_megatron(merged, megatron_module)

if labels is None:
    # [s b h] => [b s h]
    return logits.transpose(0, 1).contiguous()

loss = self.compute_language_model_loss(labels, logits)

return loss

if self.q_layernorm is not None:
    query = apply_module(self.q_layernorm)(query)

if self.k_layernorm is not None:
    key = apply_module(self.k_layernorm)(key)

assert not rotary_pos_cos_sin, "Flash-infer rope has not been tested with MLA."
assert not (
    self.training and self.cache_mla_latents
), "cache_mla_latents conflicts with training."

# hidden_states: [sq, b, h]

inference_context = deprecate_inference_params(inference_context, inference_params)
if inference_context and not inference_context.is_static_batching():
    assert (
        self.config.cache_mla_latents
    ), "currently to use dynamic backend for MLA cache mla latents must be true"

if self.config.cache_mla_latents:
    self.prepare_for_absorption()

@wrap_with_nvtx_name("megatron_policy_worker/prepare_refit_info")
def prepare_refit_info(self) -> None:
    """Prepare state dict metadata for weight refitting and IPC streaming."""
    self.refit_param_info_mcore = self._calculate_refit_param_info()

    # Collect tensor metadata for refit / hf side info
    refit_param_info_hf = {}
    # Reuse shared iterator that appends FP8 KV/Q scales when enabled
    for name, tensor in self._iter_params_with_optional_kv_scales():
        refit_param_info_hf[name] = (tensor.shape, tensor.dtype)

    return refit_param_info_hf

@torch.no_grad()
@wrap_with_nvtx_name("megatron_policy_worker/stream_weights_via_ipc_zmq")
def stream_weights_via_ipc_zmq(
    self, buffer_size_bytes: int = 0, kv_scales: Optional[dict[str, float]] = None
) -> None:
    """Stream model weights to peer process via ZMQ IPC socket."""
    self.maybe_init_zmq()

    from nemo_rl.models.policy.utils import stream_weights_via_ipc_zmq_impl

    # Use the shared implementation to append optional KV scales.
    stream_weights_via_ipc_zmq_impl(
        params_generator=self._iter_params_with_optional_kv_scales(
            kv_scales=kv_scales
        ),
        buffer_size_bytes=buffer_size_bytes,
        zmq_socket=self.zmq_socket,
        rank=self.rank,
        worker_name=str(self),
    )
